Local Ltac fast_eassumption :=
  first [ lazymatch goal with
          | |- rw_cells _ ?M ?A _ => assert_fails (is_evar M); match goal with H : rw_cells _ M A _ |- _ => exact H end
          | |- ro_cells _ _ ?A _ => match goal with H : ro_cells _ _ A _ |- _ => exact H end
          | |- bytes_at _ ?M ?A _ => assert_fails (is_evar M); match goal with H : bytes_at _ M A _ |- _ => exact H end
          | |- u8arr _ ?M ?A _ => assert_fails (is_evar M); match goal with H : u8arr _ M A _ |- _ => exact H end
          end
        | eassumption ].
(* [comment removed for export] *)
Local Ltac fit_zsizes :=
  repeat match goal with
  | |- context [Z.of_nat (cells_size ?cs)] =>
      let v := eval cbn [cells_size csize length Nat.add Z.of_nat Pos.of_succ_nat Pos.succ] in (Z.of_nat (cells_size cs)) in
      lazymatch v with Z0 => idtac | Zpos _ => idtac end;     (* [comment removed for export] *)
      change (Z.of_nat (cells_size cs)) with v
  end.
Local Tactic Notation "tr_keep" hyp(H) "over" hyp(MU) hyp(WM) "by" tactic3(tac) :=
  lazymatch type of MU with munch ?W ?m ?m' =>
  lazymatch type of H with
  | rw_cells _ _ ?A ?cs => apply (rw_cells_transport asegs W m m' A cs) in H; [| exact MU| exact WM| fit_zsizes; cbn [disjoint_from fst snd cells_size csize Nat.add]; tac]
  | ro_cells _ _ ?A ?cs => apply (ro_cells_transport asegs W m m' A cs) in H; [| exact MU| fit_zsizes; cbn [disjoint_from fst snd cells_size csize Nat.add]; tac]
  | bytes_at _ _ ?A ?bs => apply (bytes_at_transport asegs W m m' A bs) in H; [| exact MU| cbn [disjoint_from fst snd]; tac]
  | u8arr _ _ ?A ?bs => apply (u8arr_transport asegs W m m' A bs) in H; [| exact MU| exact WM| cbn [disjoint_from fst snd]; tac]
  | stk _ _ ?l ?h => apply (stk_transport_disjoint asegs W m m' l h) in H; [| exact MU| exact WM| cbn [disjoint_from fst snd]; tac]
  end end.
(* [comment removed for export] *)
Local Ltac dj_lia ::=
  first [ let a := dj_subject in progress (dj_reveal_for a); lia
        | lia
        | match goal with K : hideL _ |- _ => unfold hideL in K; lia end ].
Ltac slia_atom := first [ exact I | assumption | match goal with K : chunk_disj _ _ _ _ |- _ => exact K end | dj_lia ].
Ltac slia_conj := first [ exact I | lazymatch goal with |- _ /\ _ => split; [slia_atom| slia_conj] end | slia_atom ].
Ltac slia ::= slia_conj.

