(* [comment removed for export] *)
Ltac ipf_s1_for_exit S1F :=
  lazymatch type of S1F with rw_cells _ _ ?spa (?c0 :: ?c1 :: ?c2 :: ?rest) =>
    let R := fresh "S1R" in
    split_frameA S1F [c0; c1; c2] rest S1F R; blob_at spa;
    lazymatch goal with BL : rw_cells _ _ spa [CB _ _] |- _ => join_frameA BL R spa; rename BL into S1F end
  end.

(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac ipfx_ec_blob EC ESZ :=
  let ej := fresh "ej" in let ECj := fresh "ECj" in
  destruct (rw_cells_forget _ _ _ _ EC) as [ej ECj]; clear EC;
  lazymatch type of ECj with rw_cells _ _ _ [CB (cells_size ?ecs) _] => replace (cells_size ecs) with 24%nat in ECj by (clear - ESZ; lia) end;
  rename ECj into EC.

Ltac ipfx_prelude HH sp SD PURE WIN MU PC S1 :=
  destruct PURE as ((PCOK & LBS & LO & CEIL & PAL & EAL & SPI & ISH & IAL & DPE & DWP & DWE & SPAL & SHI) & (GAPE & SPA1 & SPA32) & LAST & APP & APE & APW);
  destruct (ipf_ff_nums _ HH _ _ _ _ _ _ _ _ _ _ _ SD) as (FF & APF & N1 & N2 & N3 & N4 & N5 & N6 & N7 & SHFF & NSF & NSP & N64);
  destruct (ipf_obj_sep _ HH _ _ _ _ _ _ _ _ _ _ _ SD) as (DPF & DEF & DWF & DPP & DEP & DWP1 & DPS & DES & DWS);
  pose proof (bytes_at_bound _ _ _ _ WIN) as WB;
  pose proof (aapp_bounds _ _ APP ltac:(clear; lia)) as (PB1 & PB2 & PB3 & PB4 & _);
  pose proof (aapp_bounds _ _ APE ltac:(clear; lia)) as (EB1 & EB2 & EB3 & EB4 & _);
  pose proof (aapp_bounds _ _ APW ltac:(clear; lia)) as (VB1 & VB2 & VB3 & VB4 & _);
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof aceil_facts as (AF1 & AF2 & _);
  unfold AIMG_TOP, AAPP_HI in PB1, PB3, EB1, EB3, VB1, VB3;
  unfold ipf_WX, ipf_W, IPF_STACK, AASSIGN_STACK, AINTRIN_STACK, AFS_STACK, AFS_FLAGS, AG_HTTP_CAT, AG_FIELD_TABLE, AG_FIELD_TABLE_GUARD in *;
  rewrite <- ?SHFF in MU; cbn [app] in MU;
  unfold ParserCoreCells in PC; cbn [pc_blim_has pc_blim pc_len pc_len0 pc_skip pc_hlim pc_state pc_f] in PC;
  unfold sh7, wz in *; rewrite ?ASHADOW_BASE_val in *;
  pose proof (aapp_not_shadowland _ _ APP) as NSP0; pose proof (aapp_not_shadowland _ _ APE) as NSE0; pose proof (aapp_not_shadowland _ _ APW) as NSV0;
  unfold ALOWSH_LO, AHI_LO in NSP0, NSE0, NSV0;
  hyde_disj; hydeL PAL; hydeL EAL; hydeL IAL; hydeL SPA32; hydeL N3; hydeL N64.

(* [comment removed for export] *)
(* [comment removed for export] *)
Ltac tr_maybe X MU1 WM1 TAC :=
  lazymatch type of MU1 with munch _ _ ?mb =>
    lazymatch type of X with
    | rw_cells _ mb _ _ => idtac
    | bytes_at _ mb _ _ => idtac
    | _ => tr_keep X over MU1 WM1 by TAC
    end end.

Ltac ipfx_unpark MU1 WM1 GAP SAV S1 TMP HI FH FR FTP SHU SHH FL BUF PC INC WIN GAPE SPA1 CEIL LO AF1 EB1 EB2 PB1 PB2 VB1 VB2 WB N1 N2 N4 N5 N6 N7 NSE0 SPI SZ1 SZT SZH BSZ DEF DEP DPE DWE :=
  unfold parked in *;
  tr_maybe GAP MU1 WM1 ltac:(clear - GAPE SPA1 CEIL LO AF1 EB2 SPI; lia);
  tr_maybe SAV MU1 WM1 ltac:(clear - GAPE SPA1 CEIL LO AF1 EB2 SPI; lia);
  tr_maybe S1 MU1 WM1 ltac:(clear - GAPE SPA1 CEIL LO AF1 EB2 SZ1 SPI; lia);
  tr_maybe TMP MU1 WM1 ltac:(clear - GAPE SPA1 CEIL LO AF1 EB2 SPI SZT; lia);
  tr_maybe HI MU1 WM1 ltac:(clear - GAPE SPA1 CEIL LO AF1 EB2 SZH SPI; lia);
  tr_maybe FH MU1 WM1 ltac:(clear - N1 N2 CEIL LO SPA1 AF1 DEF SPI; unhideL; lia);
  tr_maybe FR MU1 WM1 ltac:(clear - N1 N2 CEIL LO SPA1 AF1 DEF SPI; unhideL; lia);
  tr_maybe FTP MU1 WM1 ltac:(clear - N1 N2 CEIL LO SPA1 AF1 DEF SPI; unhideL; lia);
  tr_maybe BUF MU1 WM1 ltac:(clear - N1 N2 CEIL LO SPA1 AF1 BSZ DEF SPI; unhideL; lia);
  tr_maybe SHU MU1 WM1 ltac:(clear - N6 N7 AF1 CEIL LO SPA1 NSE0 EB1 SPI; unhideL; lia);
  tr_maybe SHH MU1 WM1 ltac:(clear - N6 N7 AF1 CEIL LO SPA1 NSE0 EB1 SPI; unhideL; lia);
  tr_maybe FL MU1 WM1 ltac:(clear - N1 N2 N4 N5 CEIL LO SPA1 AF1 DEP SPI; unhideL; lia);
  tr_maybe PC MU1 WM1 ltac:(clear - PB1 PB2 CEIL LO SPA1 AF1 DPE SPI; unhideL; lia);
  tr_maybe INC MU1 WM1 ltac:(clear - SPI CEIL LO SPA1 GAPE AF1 EB2 PB1; unhideL; lia);
  tr_maybe WIN MU1 WM1 ltac:(clear - VB1 VB2 WB CEIL LO SPA1 AF1 DWE SPI; unhideL; lia).

Section EXITS.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HH : asan_rt_hyps H.
  Hypothesis SSF8 : set_shadow_stmt 0xf8 ASET_SHADOW_F8.
  Hypothesis FREE7 : stack_free_7_stmt H.
  Hypothesis MEMCPY : asan_memcpy_stmt.
  Hypothesis ASSIGNA : aassignA_stmt.

