(* [comment removed for export] *)
Definition ipf_exit_stmt (pc : Z) (a0p : bool) (QD : Z) : Prop :=
  forall (ra sp gp tp : word) (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s2x s4x s5x s6x s7x s8x t3 t4 t5 t6 : word)
    (LF : list fframe) (m m1 : mem) (spa : Z) (gsz : nat) (gj ja jt jr jh shb : list byte) (s1r hi cb : list cell) (XS : list (Z * Z))
    (P IN E p0 lo shi ff fp last : Z) (bs : list byte) (c c1 : pcore) (pad7 pad2 : list byte) (q qlo p : Z) (ecs : list cell) (g : bool)
    (h0 h1 h2 h3 : word),
  rw_cells asegs m1 (spa + 216) [CB gsz gj] ->
  rw_cells asegs m1 (bv_unsigned sp + -104) (dof_sav s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) ->
