  rw_cells asegs m1 fp [C1 (b8 1)] ->
  rw_cells asegs m1 (ff + 32) cb -> Z.of_nat (cells_size cb) = 4104 ->
  stk asegs m1 lo spa -> mem_inv asegs m1 ->
  ipf_side H LF m m1 lo shi ff fp P E p0 (Z.of_nat (length bs)) ->
  munch (ipf_WX H lo sp P IN E ff fp ++ XS) m m1 -> Forall (fs_scratch H ((7, ff, fp) :: LF)) XS -> wmono asegs m m1 ->
  rw_cells asegs m1 P (ParserCoreCells c1 pad7 pad2) -> dof_core c c1 ->
  rw_cells asegs m1 IN [C8 (wz q)] ->
  rw_cells asegs m1 E (ErrCodeCells E') -> (E' = EC_clear \/ http_fail E') ->
  bytes_at asegs m1 p0 bs -> APfTab m1 -> (AFieldTabZero m1 \/ FT m1) -> FTInit m1 -> AHttpCat m1 g ->
  ipf_bpure sp spa gsz P IN E lo shi c p0 last bs -> bv_unsigned ra mod 2 = 0 ->
  qlo <= p + 2 -> p0 <= p -> p + 2 <= p0 + Z.of_nat (length bs) ->
  evt asegs (ipf_ret_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc LF P IN E lo shi c pad7 pad2 p0 bs qlo m)
    (MS (mkR rax (wz spa) gp tp t0 t1 t2 sp (wz spa) a0 a1 a2 a3 a4 a5 a6 a7
             s2x (wz E) s4x s5x s6x s7x s8x (wz (E + 16)) (wz ASHADOW_BASE) (wz IN) t3 t4 t5 t6)
